            className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500 focus:bg-white focus:outline-none transition-all text-sm"
          />
          {globalSearchQuery && (
            <button 
              onClick={() => setGlobalSearchQuery('')}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
            >
              <X size={14} />
            </button>
          )}
        </div>

        {currentView === 'requests' && (
          <div className="flex gap-2">
            {['All', 'Pending', 'In Progress'].map((f) => (
               <button
                 key={f}
                 onClick={() => setFilter(f as any)}
                 className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                   filter === f ? 'bg-gray-800 text-white' : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
                 }`}
               >
                 {f}
               </button>
            ))}
          </div>
        )}
      </div>

      {currentView === 'requests' && renderRequestsTable()}
      {currentView === 'analytics' && renderAnalytics()}
      {currentView === 'vendors' && renderVendorsTable()}
      {currentView === 'clients' && renderClientsTable()}
      {currentView === 'supervisors' && renderSupervisorsTable()}

      {/* Click outside listener for dropdown */}
      {activeDropdown && (
        <div 
          className="fixed inset-0 z-10 bg-transparent"
          onClick={() => setActiveDropdown(null)}
        />
      )}
    </div>
  );
};

